class Solution:
    def shortestSuperstring(self, s1: str, s2: str) -> str:
        def merge(a, b):
            if b in a:
                return a
            if a in b:
                return b
            for k in range(min(len(a), len(b)), 0, -1):
                if a.endswith(b[:k]):
                    return a + b[k:]
            return a + b
        x, y = merge(s1, s2), merge(s2, s1)
        return x if len(x) <= len(y) else y

