class Solution {
public:
    string merge(const string& a, const string& b) {
        if (a.find(b) != string::npos) return a;
        if (b.find(a) != string::npos) return b;
        int mx = min(a.size(), b.size());
        for (int k = mx; k > 0; k--)
            if (a.compare(a.size() - k, k, b, 0, k) == 0)
                return a + b.substr(k);
        return a + b;
    }
    string shortestSuperstring(string s1, string s2) {
        string x = merge(s1, s2), y = merge(s2, s1);
        return x.size() <= y.size() ? x : y;
    }
};

